INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66696856', 66696856, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Akses Data Citra Satelit Optik Very High Resolution (VHR) melalui Virtual Reception System (VRS)', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 20000000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 paket', 'Pengadaan layanan akses data citra satelit optik resolusi sangat tinggi (VHR) melalui Virtual Reception System (VRS) untuk mendukung kebutuhan BRIN Tahun Anggaran 2026, termasuk penyediaan akses citra arsip dan/atau tasking, lisensi tunggal pemanfaatan data untuk seluruh instansi Pemerintah Republik Indonesia, platform dan tools untuk tasking, pengelolaan data, distribusi data, serta program transfer teknologi/pelatihan operasional VRS bagi minimal 10 personel BRIN selama minimal 3 hari. Ruang lingkup juga mencakup jaminan volume akses sumber daya satelit sesuai kebutuhan layanan.', 'Penyediaan layanan data citra satelit optik VHR dengan ketentuan minimal: Akses data VHR melalui VRS minimal 200.000 km2 per tahun dengan parameter cloud cover ≤ 15%, incident angle ≤ 20°, dan resolusi spasial pankromatik nadir ≤ 0,5 m. Menyediakan resolusi spektral minimal 4 kanal multispektral (Blue, Green, Red, NIR) dan 1 kanal pankromatik. Menyediakan resolusi pankromatik ≤ 0,3 m dan/atau ≤ 0,5 m. Didukung minimal 2 satelit konstelasi. Menyediakan informasi mission planning satelit sampai masa kontrak berakhir. Memiliki dan dapat membuktikan kapasitas akuisisi data di wilayah Indonesia dengan arsip data VHR hingga 400.000 km2 per tahun untuk tahun 2024 dan 2025, termasuk distribusi spasial data dalam shapefile beserta atribut ID data, tanggal akuisisi, cloud cover, incident angle, dan quicklook bereferensi geografis. Menyediakan minimal 2 level produksi data, yaitu koreksi radiometrik dan systematic orthorectification dengan DEM/Chip, dengan CE90 ≤ 10 m. Data arsip tahun 2026 dan tahun sebelumnya dapat diakses secara daring selama masa kontrak. Tersedia web portal online untuk permintaan data arsip. Koleksi citra daring tersedia maksimal 48 jam setelah permintaan data. Menyediakan single license untuk seluruh instansi Pemerintah Republik Indonesia. Menyediakan instalasi, konfigurasi, pengujian fungsi sistem, dan dokumen teknis/brosur/white paper sesuai persyaratan administrasi dan teknis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2943015);
