INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66697071', 66697071, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Mesin Pembengkok Pipa Semi Otomatis atau Setara', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 800000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Unit', 'Pengadaan 1 unit mesin pembengkok pipa semi otomatis atau setara untuk mendukung kegiatan fabrikasi, manufaktur, perakitan, dan/atau pengembangan prototipe berbahan pipa logam. Ruang lingkup pekerjaan meliputi penyediaan barang dalam kondisi baru, pengiriman ke lokasi kerja, instalasi/penempatan, uji fungsi, penyerahan dokumen teknis, manual penggunaan, kartu garansi, serta dukungan layanan purna jual.', 'Pengadaan mesin pembengkok pipa semi otomatis atau setara, kondisi baru, dengan spesifikasi minimal sebagai berikut: Jenis alat: mesin pembengkok pipa semi otomatis atau setara. Sistem kerja: hidrolik atau setara. Mode operasi: semi otomatis atau setara. Peruntukan: untuk pekerjaan pembengkokan pipa logam pada kegiatan fabrikasi/manufaktur/prototyping. Kapasitas material: mampu digunakan untuk material pipa baja karbon, stainless steel, aluminium, atau setara. Kapasitas pembengkokan pipa bulat: mampu membengkokkan pipa bulat dengan diameter nominal minimal 1/2 inci sampai dengan 3 inci atau setara. Kapasitas pembengkokan pipa kotak/persegi: mampu membengkokkan pipa kotak/persegi panjang dengan ukuran kerja minimal setara 25 mm x 25 mm x 1,8 mm dan/atau ukuran lain yang setara sesuai kebutuhan operasional. Ketebalan material: mampu menangani ketebalan dinding pipa minimal sampai 3 mm atau setara, menyesuaikan jenis material dan diameter pipa. Sudut pembengkokan: sudut bending dapat diatur minimal sampai 180 derajat atau setara. Radius pembengkokan: memiliki kemampuan radius pembengkokan maksimal/minimal kerja setara 300 mm sampai 350 mm atau setara, tergantung dimensi pipa dan dies yang digunakan. Kecepatan kerja: kecepatan pembengkokan minimal 5 rpm atau setara. Tekanan hidrolik: tekanan kerja hidrolik minimal 21 MPa atau setara. Daya motor utama: minimal 11 kW atau setara. Catu daya: menggunakan suplai listrik 3 fasa yang sesuai dengan instalasi kelistrikan di lokasi pengguna, atau setara. Sistem kendali: dilengkapi panel kontrol, tombol operasi, indikator kerja, emergency stop, atau setara. Dies/cetakan: dilengkapi set dies pembengkok pipa minimal untuk ukuran nominal 1/2 inci, 3/4 inci, 1 inci, 1 1/4 inci, 1 1/2 inci, 2 inci, 2 1/2 inci, dan 3 inci atau setara. Kelengkapan standar: termasuk tool kit standar, komponen pengoperasian, dan aksesori utama yang diperlukan agar alat dapat difungsikan dengan baik. Konstruksi mesin: rangka/struktur mesin kuat, stabil, dan layak digunakan di workshop/laboratorium. Dimensi alat: dimensi keseluruhan maksimal sekitar 430 cm x 132 cm x 130 cm atau setara, atau ukuran lain yang setara sepanjang masih sesuai dengan ruang penempatan dan fungsi kerja. Berat alat: berat keseluruhan maksimal sekitar 3.500 kg atau setara. Dokumen teknis: disertai brosur/spesifikasi teknis, manual operasi, daftar komponen utama, dan identitas produk. Garansi: garansi minimal 1 tahun atau setara. Layanan purna jual: tersedia dukungan teknis, layanan perawatan, dan ketersediaan suku cadang atau setara. Uji fungsi: penyedia wajib melakukan pemeriksaan dan uji fungsi saat serah terima. Pelatihan singkat: apabila diperlukan, penyedia memberikan pelatihan/pengarahan pengoperasian kepada operator minimal 1 kali sesi. Kondisi barang: barang baru, bukan barang bekas, bukan barang rekondisi, dan siap operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2943835);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66695851', 66695851, 'analyze_legacy', 'Kota Pekanbaru', 'kabkota', 'Sekretariat DPRD', 'Sewa Kursi an. SYAFRI SYARIF, SE', 'Jasa Lainnya', 'Pengadaan Langsung', 'Riau, Pekanbaru (Kota)', 45000000, 'January 2026', 'APBD', 1, 1, '-', 'Sewa Kursi', ';;;;;', 45000000, 'high', 'Pengadaan berupa sewa kursi atas nama individu menimbulkan indikasi penggunaan anggaran yang tidak proporsional dan berpotensi tidak relevan dengan kebutuhan kelembagaan. Nilai anggaran relatif besar untuk objek sewa yang sangat umum, sementara rincian spesifikasi tidak memadai untuk menilai kewajaran biaya.', NULL, NULL, 3, 1, 1, 1, 1, 2943836);
