INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66696667', 66696667, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Preventive Maintenance Alat Riset Pada BRIN KST B.J. Habibie (Serpong)', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 35000000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '15 paket', '1. Pemeriksaan Awal (Initial Inspection) : - Melakukan pengecekan kondisi umum alat (fisik dan fungsi). - Verifikasi kelengkapan komponen utama dan pendukung. - Pemeriksaan indikator kinerja alat sesuai spesifikasi pabrikan. - Identifikasi potensi kerusakan atau penurunan performa. 2. Pembersihan (Cleaning) : - Pembersihan bagian luar (external cleaning) dari debu dan kotoran. - Pembersihan bagian dalam (internal cleaning) sesuai standar teknis alat. - Pembersihan komponen sensitif (optik, sensor, probe, dll) menggunakan metode dan bahan yang direkomendasikan. 3 Pemeriksaan dan Pengujian Komponen : - Pemeriksaan komponen mekanik (fan, motor, valve, dll). - Pemeriksaan komponen elektrik dan elektronik (power supply, PCB, konektor). - Pengujian sistem kontrol dan interface. - Pengujian fungsi keseluruhan alat (functional test). 4 Kalibrasi dan Penyesuaian (Calibration & Adjustment) : - Kalibrasi alat sesuai standar operasional atau referensi pabrikan. - Penyesuaian parameter operasional agar sesuai spesifikasi. - Verifikasi hasil kalibrasi dengan standar acuan. 5 Pelumasan dan Penggantian Minor : - Pelumasan bagian mekanik yang membutuhkan. - Penggantian komponen habis pakai (consumables) seperti: Filter, Seal/O-ring, Lampu/filamen (jika diperlukan) - Pengencangan koneksi dan baut yang longgar. 6. Pengujian Kinerja (Performance Test) - Uji performa alat setelah dilakukan maintenance. - Membandingkan hasil dengan spesifikasi teknis atau baseline awal. - Dokumentasi hasil pengujian. 7. Troubleshooting Ringan : - Identifikasi dan perbaikan gangguan ringan. - Rekomendasi perbaikan lanjutan jika ditemukan kerusakan mayor. 8. Dokumentasi dan Pelaporan - Penyusunan laporan hasil preventive maintenance yang memuat: - Kondisi alat sebelum dan sesudah pekerjaan - Tindakan yang dilakukan - Hasil pengujian dan kalibrasi - Daftar komponen yang diganti - Rekomendasi tindak lanjut - Pengisian checklist maintenance', '1. Pemeriksaan Awal (Initial Inspection) : - Melakukan pengecekan kondisi umum alat (fisik dan fungsi). - Verifikasi kelengkapan komponen utama dan pendukung. - Pemeriksaan indikator kinerja alat sesuai spesifikasi pabrikan. - Identifikasi potensi kerusakan atau penurunan performa. 2. Pembersihan (Cleaning) : - Pembersihan bagian luar (external cleaning) dari debu dan kotoran. - Pembersihan bagian dalam (internal cleaning) sesuai standar teknis alat. - Pembersihan komponen sensitif (optik, sensor, probe, dll) menggunakan metode dan bahan yang direkomendasikan. 3 Pemeriksaan dan Pengujian Komponen : - Pemeriksaan komponen mekanik (fan, motor, valve, dll). - Pemeriksaan komponen elektrik dan elektronik (power supply, PCB, konektor). - Pengujian sistem kontrol dan interface. - Pengujian fungsi keseluruhan alat (functional test). 4 Kalibrasi dan Penyesuaian (Calibration & Adjustment) : - Kalibrasi alat sesuai standar operasional atau referensi pabrikan. - Penyesuaian parameter operasional agar sesuai spesifikasi. - Verifikasi hasil kalibrasi dengan standar acuan. 5 Pelumasan dan Penggantian Minor : - Pelumasan bagian mekanik yang membutuhkan. - Penggantian komponen habis pakai (consumables) seperti: Filter, Seal/O-ring, Lampu/filamen (jika diperlukan) - Pengencangan koneksi dan baut yang longgar. 6. Pengujian Kinerja (Performance Test) - Uji performa alat setelah dilakukan maintenance. - Membandingkan hasil dengan spesifikasi teknis atau baseline awal. - Dokumentasi hasil pengujian. 7. Troubleshooting Ringan : - Identifikasi dan perbaikan gangguan ringan. - Rekomendasi perbaikan lanjutan jika ditemukan kerusakan mayor. 8. Dokumentasi dan Pelaporan - Penyusunan laporan hasil preventive maintenance yang memuat: - Kondisi alat sebelum dan sesudah pekerjaan - Tindakan yang dilakukan - Hasil pengujian dan kalibrasi - Daftar komponen yang diganti - Rekomendasi tindak lanjut - Pengisian checklist maintenance', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2943865);
