INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66699845', 66699845, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Differential Scanning Calorimeter (DSC) untuk Analisis Termal Material', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 2450000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Unit', 'Pengadaan 1 unit perangkat Differential Scanning Calorimeter (DSC) untuk pengukuran sifat termal material, pengamatan transisi fasa seperti melting, glass transition, kristalisasi, dan dekomposisi eksotermik, berikut perangkat pendukung operasional, instalasi, commissioning, pelatihan, dan layanan purna jual.', 'Pengadaan Differential Scanning Calorimeter (DSC) atau setara dengan spesifikasi minimum sebagai berikut: Tipe alat: Differential Scanning Calorimeter untuk analisis termal material. Prinsip pengukuran: power compensation atau metode setara dengan performa minimal ekuivalen. Desain furnace: double furnace design atau setara. Material furnace: paduan logam tahan temperatur tinggi dengan performa setara. Sensor temperatur: sensor temperatur presisi tinggi berbasis resistance thermometer/platinum resistance thermometer atau setara. Rentang temperatur kerja minimum: -170 °C sampai 750 °C atau lebih baik. Akurasi temperatur maksimum: ±0,05 °C atau lebih baik. Presisi temperatur maksimum: ±0,008 °C atau lebih baik. Dynamic range minimum: ±175 mW. Kecepatan pemanasan terkontrol minimum: 0,01 sampai 300 °C/menit, dan diutamakan mendukung high-speed scanning hingga 750 °C/menit atau setara. Kecepatan pendinginan terkontrol minimum: 0,01 sampai 150 °C/menit, dan diutamakan mendukung rapid cooling hingga 750 °C/menit atau setara. Data acquisition minimum: 40 data point/detik, diutamakan 100 data point/detik atau lebih baik. Akurasi kalorimetrik maksimum: < ±0,2%. Presisi kalorimetrik maksimum: < ±0,3%. Resolusi digital maksimum: 0,18 µW atau lebih baik. Mendukung gas purge minimal: Nitrogen, Helium, Compressed Air, Oxygen, dan Argon atau setara. Mendukung pengujian aplikasi minimal untuk: studi kinetika isotermal, curing polimer, evaluasi peningkatan proses dan produk, riset industri dan akademik, simulasi proses pada material/plastik. Software pengendali instrumen harus termasuk dan mampu untuk akuisisi data, analisis DSC, isothermal kinetics, scanning kinetics, specific heat, dan purity analysis atau setara. Termasuk aksesori operasional minimal: software pengoperasian instrumen, sistem pendingin/cooling system yang kompatibel, pan dan cover aluminium, sample crimp press standar, reference/calibration kit, suplai/regulator gas yang diperlukan untuk commissioning, UPS minimum 3 kVA, trafo/isolation transformer minimum 3 kVA, 1 set komputer pengendali minimal Core i7 atau setara, monitor, dan printer. Dimensi dan bobot alat menyesuaikan desain pabrikan. Kondisi pengadaan harus termasuk: instalasi, commissioning sampai alat berfungsi baik, pelatihan operator, garansi minimal 1 tahun, layanan purna jual minimal 1 tahun termasuk kunjungan maintenance berkala.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2945817);
