INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66699863', 66699863, 'analyze_legacy', 'Kab. Nganjuk', 'kabkota', 'Rumah Sakit Daerah Nganjuk', 'Belanja Jasa Tenaga Penanganan Prasarana dan Sarana Umum (Biaya Penataan dan Pemusnahan Dokumen RSUD Nganjuk)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Nganjuk (Kab.)', 185500000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Biaya Penataan dan Pemusnahan Dokumen RSUD Nganjuk', 'A. Ruang Lingkup Pekerjaan Penataan Arsip 1. Identifikasi dan inventarisasi dokumen/arsip pada unit kerja di lingkungan RSUD Kabupaten Nganjuk 2. Pemilahan arsip berdasarkan jenis, tahun, dan nilai guna 3. Pengelompokan arsip sesuai klasifikasi kearsipan yang berlaku 4. Penataan arsip ke dalam boks/folder arsip 5. Pelabelan dan penyusunan arsip secara sistematis 6. Penyusunan daftar arsip (Daftar Arsip Aktif/Inaktif) 7. Penyusunan berita acara hasil penataan arsip B. Ruang Lingkup Pekerjaan Penilaian dan Penyusutan Arsip 1. Identifikasi arsip yang telah habis masa retensinya sesuai Jadwal Retensi Arsip (JRA) 2. Pemisahan arsip permanen dan arsip yang diusulkan untuk dimusnahkan 3. Penyusunan daftar usul pemusnahan arsip 4. Koordinasi dengan unit terkait dalam proses verifikasi arsip C. Ruang Lingkup Pekerjaan Pemusnahan Dokumen 1. Pelaksanaan pemusnahan arsip yang telah mendapatkan persetujuan sesuai ketentuan 2. Metode pemusnahan dilakukan secara aman dan menjaga kerahasiaan dokumen 3. Pemusnahan dilakukan dengan metode penghancuran (shredding) atau metode lain sesuai standar kearsipan 4. Penyusunan berita acara pemusnahan arsip 5. Dokumentasi kegiatan pemusnahan arsip D. Output/Deliverables 1. Arsip tertata sesuai kaidah kearsipan 2. Daftar arsip hasil penataan 3. Daftar arsip usul musnah 4. Berita acara penataan arsip 5. Berita acara pemusnahan arsip 6. Dokumentasi kegiatan E. Tenaga Pelaksana 1. Tenaga ahli kearsipan 2. Tenaga teknis penataan arsip 3. Tenaga pendukung operasional F. Waktu Pelaksanaan Pelaksanaan kegiatan disesuaikan dengan kebutuhan RSUD Kabupaten Nganjuk sampai seluruh arsip tertata dan arsip yang memenuhi syarat selesai dimusnahkan. G. Metodologi Metode dalam melaksanakan kegiatan pengelolaan dokumen/arsip baik dalam melaksanakan pemberkasan/pengelompokan menggunakan payung hukum kearsipan yang tersedia, yaitu: 1. Undang – Undang No. 43 Tahun 2009 Tentang kearsipan. 2. PP No. 28 Tentang Pelaksanaan UU No. 43 Tahun 2009 Tentang Kearsipan. 3. Perka ANRI No. 9 Tahun 2018 Tentang Pedoman pemeliharaan Arsip Dinamis. 4. Perka ANRI No. 31 Tahun 2015 Pasal 18 Tentang Pedoman Pembentukan Depot Arsip. 5. Peraturan Bupati Nganjuk Nomor 46 Tahun 2017 Tentang Pedoman Pengelolaan Arsip Dinamis Inaktif. 6. Peraturan Bupati Nganjuk Nomor 16 Tahun 2023 Tentang Kode Klasifikasi di Lingkungan Kabupaten Nganjuk. 7. Peraturan Bupati Nganjuk Nomor 18 Tahun 2024 Tentang Penetapan Sistem Klasifikasi Keamanan dan Hak Akses Arsip Dinamis Pemerintah Kabupaten Nganjuk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2946507);
