INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66694092', 66694092, 'analyze_legacy', 'Kota Pekanbaru', 'kabkota', 'Sekretariat DPRD', 'Sewa Kursi an. DAVIT MARIHOT SILABAN, M.Si', 'Jasa Lainnya', 'Pengadaan Langsung', 'Riau, Pekanbaru (Kota)', 45000000, 'January 2026', 'APBD', 1, 1, '-', 'Sewa Kursi', ';;;;;;', 45000000, 'high', 'Pengadaan sewa kursi yang mencantumkan nama individu pada judul menimbulkan indikasi penggunaan anggaran untuk kebutuhan yang sangat spesifik/personal dan kurang mencerminkan kebutuhan kelembagaan yang umum. Dengan detail spesifikasi yang tidak memadai, seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2946844);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66701215', 66701215, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Upgrade Software, Antarmuka Komunikasi, Komputer Pengendali, Kalibrasi, dan Pemeliharaan untuk Atomic Absorption Spectrometer (AAS)', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 170000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Set', 'Pengadaan perangkat lunak, perangkat antarmuka komunikasi instrumen, komputer pengendali, jasa instalasi, integrasi, pengujian fungsi, kalibrasi, dan pemeliharaan untuk mendukung operasional alat Atomic Absorption Spectrometer (AAS) yang sudah ada pada laboratorium. Paket ini dimaksudkan untuk memulihkan/meningkatkan kemampuan operasional sistem AAS eksisting agar dapat digunakan untuk kegiatan layanan teknis laboratorium secara andal, kompatibel, dan terdokumentasi.', 'Pengadaan upgrade software, perangkat antarmuka komunikasi, komputer pengendali, kalibrasi, dan pemeliharaan untuk Atomic Absorption Spectrometer (AAS) eksisting, dengan ketentuan minimal: kompatibel dan dapat terintegrasi dengan instrumen AAS yang telah ada di laboratorium; perangkat lunak mampu mendukung pengendalian instrumen, akuisisi data, pengolahan data, penyimpanan data, dan pencetakan laporan; dilengkapi perangkat antarmuka komunikasi beserta kabel, driver, adaptor, dan kelengkapan lain yang diperlukan agar sistem dapat berfungsi normal; dilengkapi 1 unit komputer pengendali dengan spesifikasi memadai untuk operasional instrumen laboratorium; termasuk instalasi, konfigurasi, integrasi sistem, uji fungsi, dan memastikan alat dapat dioperasikan kembali secara normal; termasuk kalibrasi/verifikasi kinerja pasca-instalasi sesuai SOP laboratorium atau ketentuan yang berlaku; termasuk pemeliharaan/servis awal agar sistem siap operasional; termasuk pelatihan singkat operator, dokumentasi teknis, manual penggunaan, dan lisensi resmi; barang yang disediakan harus baru, legal, dan bukan barang bekas/rekondisi; dilengkapi garansi dan dukungan purna jual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2946845);
