INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66704009', 66704009, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Aerosol Monitor untuk Pemantauan Radioaktivitas Udara Dalam Ruangan', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 1500000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Paket', 'Pengadaan alat aerosol monitor untuk pemantauan radioaktivitas udara dalam ruangan secara berkelanjutan (continuous monitoring), termasuk instalasi, pengujian, pelatihan operator, dan dokumentasi teknis. Paket ini dibutuhkan untuk mendukung pemenuhan ketentuan keselamatan/pengawasan dan tindak lanjut kebutuhan teknis laboratorium.', 'Pengadaan 1 paket Aerosol Monitor untuk pemantauan radioaktivitas aerosol udara secara kontinu (continuous monitoring) pada area indoor, dengan spesifikasi minimal sebagai berikut: mampu melakukan pemantauan aerosol radioaktif udara secara kontinu 24 jam/7 hari; mampu mengukur parameter radioaktivitas udara minimal Gross Alpha-Beta, dan/atau memiliki kapabilitas pemantauan radionuklida yang relevan dengan kebutuhan operasional laboratorium; memiliki rentang pengukuran minimal 0 sampai 1000 Bq/m3; diperuntukkan untuk penggunaan dalam ruangan (indoor); memiliki sistem pengambilan sampel udara terintegrasi, sistem deteksi, tampilan hasil pengukuran, dan perekaman data; memiliki data logging dan penyimpanan data hasil pemantauan; memiliki fitur alarm/peringatan apabila hasil pemantauan melebihi nilai ambang yang ditetapkan; mampu menampilkan nilai pengukuran secara real time dan histori data pengukuran; catu daya 220–240 VAC, 50 Hz atau yang setara dan sesuai standar kelistrikan Indonesia; termasuk aksesori standar operasi, instalasi, commissioning, uji fungsi, pelatihan operator, dokumentasi teknis, garansi, dan dukungan purna jual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2947565);
